{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.RTS_ALLOCATABILITY as WITH base_raw AS ( SELECT UPPER(TRIM(SKU)) AS sku_group, REGEXP_REPLACE(UPPER(TRIM(SKU)), \'-[^-]+$\', \'\') AS sku_code, REGEXP_SUBSTR(UPPER(TRIM(SKU)), \'[^-]+$\') AS colour_code, vendor AS vendor_name, warehouse, online_qty, REGEXP_REPLACE( REPLACE( REPLACE( REPLACE( REPLACE(UPPER(TRIM(\"Logic PO\")), \'/\', \',\'), \'&\', \',\'), \'.\', \'-\'), \' \', \'\'), \'\\s+\', \'\') AS logic_po_clean, date_of_entry, delivey_Date FROM snitch_db.maplemonk.online_goods_main WHERE delivey_Date IS NULL AND SKU IS NOT NULL ), inwards_month_remarks AS ( SELECT UPPER(TRIM(cleaned_sku)) AS cleaned_sku, MAX(UPPER(TRIM(remarks_final))) AS remarks_final FROM snitch_db.maplemonk.inwards_list_mom_v2_sku_list_with_month_remarks WHERE cleaned_sku IS NOT NULL GROUP BY 1 ), meta_mapping AS ( SELECT sku_group, l1_category, category, meta1, meta2, meta3 FROM snitch_db.maplemonk.meta_mapping_cogs_sku ), base AS ( SELECT br.sku_group, br.sku_code, br.colour_code, br.vendor_name, br.warehouse, TRY_TO_NUMBER(REPLACE(TRIM(br.online_qty), \',\', \'\')) AS online_qty, br.logic_po_clean, br.date_of_entry, CASE WHEN br.warehouse ILIKE \'Yelahanka-2\' THEN TRY_TO_NUMBER(REPLACE(TRIM(br.online_qty), \',\', \'\')) ELSE 0 END AS south_qty, CASE WHEN br.warehouse ILIKE \'North\' THEN TRY_TO_NUMBER(REPLACE(TRIM(br.online_qty), \',\', \'\')) ELSE 0 END AS north_qty, CASE WHEN br.warehouse ILIKE \'Yelahanka-2\' OR br.warehouse ILIKE \'North\' THEN TRY_TO_NUMBER(REPLACE(TRIM(br.online_qty), \',\', \'\')) ELSE 0 END AS total_qty, CASE WHEN br.date_of_entry IS NOT NULL THEN 1 ELSE 0 END AS has_date_of_entry, CASE WHEN br.warehouse ILIKE \'Yelahanka-2\' THEN TO_VARCHAR(br.date_of_entry) END AS inspection_date_south, CASE WHEN br.warehouse ILIKE \'North\' THEN TO_VARCHAR(br.date_of_entry) END AS inspection_date_north, imr.remarks_final AS planned_month FROM base_raw br LEFT JOIN inwards_month_remarks imr ON UPPER(TRIM(br.sku_group)) = imr.cleaned_sku ), mrp AS ( SELECT UPPER(TRIM(sku_group)) AS sku_group, MAX(PO_MRP) AS mrp FROM snitch_db.maplemonk.logic_purchase_order WHERE PO_MRP > 0 AND sku_group IS NOT NULL GROUP BY 1 ), po_split AS ( SELECT *, CASE WHEN REGEXP_LIKE(logic_po_clean, \'^(POF|POJ|POB|PBJ)[0-9]{2}SW[0-9]+-NW[0-9]+$\') THEN REGEXP_SUBSTR(logic_po_clean, \'^(POF|POJ|POB|PBJ)[0-9]{2}\') || \'-\' || REGEXP_SUBSTR(logic_po_clean, \'SW([0-9]+)\', 1, 1, \'e\', 1) WHEN SPLIT_PART(logic_po_clean, \',\', 2) <> \'\' THEN SPLIT_PART(logic_po_clean, \',\', 1) WHEN UPPER(warehouse) = \'YELAHANKA-2\' THEN logic_po_clean END AS south_po, CASE WHEN REGEXP_LIKE(logic_po_clean, \'^(POF|POJ|POB|PBJ)[0-9]{2}SW[0-9]+-NW[0-9]+$\') THEN REGEXP_SUBSTR(logic_po_clean, \'^(POF|POJ|POB|PBJ)[0-9]{2}\') || \'-\' || REGEXP_SUBSTR(logic_po_clean, \'NW([0-9]+)\', 1, 1, \'e\', 1) WHEN SPLIT_PART(logic_po_clean, \',\', 2) <> \'\' AND REGEXP_LIKE(SPLIT_PART(logic_po_clean, \',\', 2), \'^(POF|POJ|POB|PBJ)[0-9]{2}-[0-9]+$\') THEN SPLIT_PART(logic_po_clean, \',\', 2) WHEN SPLIT_PART(logic_po_clean, \',\', 2) <> \'\' THEN SPLIT_PART(SPLIT_PART(logic_po_clean, \',\', 1), \'-\', 1) || \'-\' || SPLIT_PART(logic_po_clean, \',\', 2) WHEN warehouse ILIKE \'%NORTH%\' THEN logic_po_clean END AS north_po, CASE WHEN warehouse ILIKE \'%NORTH%\' THEN CASE WHEN REGEXP_LIKE(logic_po_clean, \'^(POF|POJ|POB|PBJ)[0-9]{2}SW[0-9]+-NW[0-9]+$\') THEN REGEXP_SUBSTR(logic_po_clean, \'^(POF|POJ|POB|PBJ)[0-9]{2}\') || \'-\' || REGEXP_SUBSTR(logic_po_clean, \'NW([0-9]+)\', 1, 1, \'e\', 1) WHEN SPLIT_PART(logic_po_clean, \',\', 2) <> \'\' AND REGEXP_LIKE(SPLIT_PART(logic_po_clean, \',\', 2), \'^(POF|POJ|POB|PBJ)[0-9]{2}-[0-9]+$\') THEN SPLIT_PART(logic_po_clean, \',\', 2) WHEN SPLIT_PART(logic_po_clean, \',\', 2) <> \'\' THEN SPLIT_PART(SPLIT_PART(logic_po_clean, \',\', 1), \'-\', 1) || \'-\' || SPLIT_PART(logic_po_clean, \',\', 2) ELSE logic_po_clean END WHEN UPPER(warehouse) = \'YELAHANKA-2\' THEN CASE WHEN REGEXP_LIKE(logic_po_clean, \'^(POF|POJ|POB|PBJ)[0-9]{2}SW[0-9]+-NW[0-9]+$\') THEN REGEXP_SUBSTR(logic_po_clean, \'^(POF|POJ|POB|PBJ)[0-9]{2}\') || \'-\' || REGEXP_SUBSTR(logic_po_clean, \'SW([0-9]+)\', 1, 1, \'e\', 1) WHEN SPLIT_PART(logic_po_clean, \',\', 2) <> \'\' THEN SPLIT_PART(logic_po_clean, \',\', 1) ELSE logic_po_clean END ELSE logic_po_clean END AS purchase_order FROM base ), repeat_remarks AS ( SELECT CASE WHEN REGEXP_LIKE( UPPER(TRIM(sku_group)), \'^[A-Z0-9]+-[0-9]{1}\s+.*\' ) THEN REGEXP_REPLACE( REGEXP_SUBSTR(UPPER(TRIM(sku_group)), \'^[A-Z0-9]+-[0-9]{1}\'), \'-([0-9])$\', \'-0\\1\' ) WHEN UPPER(TRIM(sku_group)) LIKE \'SN%\' OR UPPER(TRIM(sku_group)) LIKE \'BP%\' THEN UPPER(TRIM(sku_group)) WHEN UPPER(TRIM(sku_group)) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+-[^-]+\'))) ELSE CASE WHEN UPPER(TRIM(sku_group)) LIKE \'%-%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+\'))) ELSE UPPER(TRIM(sku_group)) END END AS sku_group, SUM(gross_quantity) AS gross_qty, \'Repeat\' AS repeat_remarks FROM snitch_db.maplemonk.horizontal_sales_categories GROUP BY 1 HAVING SUM(gross_quantity) > 0 ), photoshoot_dedup AS ( SELECT UPPER(TRIM(sku_group)) AS sku_group, MAX(shoot_date) AS shoot_date, MAX(sample_received_date) AS sample_received_date FROM snitch_db.maplemonk.sku_group_sample_to_live GROUP BY UPPER(TRIM(sku_group)) ), po_base AS ( SELECT REGEXP_REPLACE( CASE WHEN REGEXP_LIKE(UPPER(TRIM(sku_group)), \'^MP[A-Z]{2}[0-9]\') AND NOT REGEXP_LIKE(UPPER(TRIM(sku_group)), \'^MP-\') THEN \'MP-\' || SUBSTR(UPPER(TRIM(sku_group)), 3) WHEN REGEXP_LIKE(UPPER(TRIM(sku_group)), \'.*-[0-9]$\') THEN REGEXP_REPLACE(UPPER(TRIM(sku_group)), \'-([0-9])$\', \'-0\\1\') ELSE UPPER(TRIM(sku_group)) END, \'-[^-]+$\', \'\' ) AS sku_code, REGEXP_SUBSTR( CASE WHEN REGEXP_LIKE(UPPER(TRIM(sku_group)), \'^MP[A-Z]{2}[0-9]\') AND NOT REGEXP_LIKE(UPPER(TRIM(sku_group)), \'^MP-\') THEN \'MP-\' || SUBSTR(UPPER(TRIM(sku_group)), 3) WHEN REGEXP_LIKE(UPPER(TRIM(sku_group)), \'.*-[0-9]$\') THEN REGEXP_REPLACE(UPPER(TRIM(sku_group)), \'-([0-9])$\', \'-0\\1\') ELSE UPPER(TRIM(sku_group)) END, \'[^-]+$\' ) AS colour_code FROM snitch_db.maplemonk.logic_purchase_order WHERE sku_group LIKE \'%-%\' ), collection_dedup AS ( SELECT CASE WHEN REGEXP_LIKE(UPPER(TRIM(sku)), \'^MP[A-Z]{2}[0-9]\') AND NOT REGEXP_LIKE(UPPER(TRIM(sku)), \'^MP-\') THEN \'MP-\' || SUBSTR(UPPER(TRIM(sku)), 3) WHEN REGEXP_LIKE(UPPER(TRIM(sku)), \'.*-[0-9]$\') THEN REGEXP_REPLACE(UPPER(TRIM(sku)), \'-([0-9])$\', \'-0\\1\') ELSE UPPER(TRIM(sku)) END AS sku_group, ANY_VALUE(collection) AS collection FROM snitch_db.maplemonk.collection_sku_mapped GROUP BY 1 ), sku_class AS ( SELECT CASE WHEN REGEXP_LIKE(UPPER(TRIM(sku_group)), \'^MP[A-Z]{2}[0-9]\') AND NOT REGEXP_LIKE(UPPER(TRIM(sku_group)), \'^MP-\') THEN \'MP-\' || SUBSTR(UPPER(TRIM(sku_group)), 3) WHEN REGEXP_LIKE(UPPER(TRIM(sku_group)), \'.*-[0-9]$\') THEN REGEXP_REPLACE(UPPER(TRIM(sku_group)), \'-([0-9])$\', \'-0\\1\') ELSE UPPER(TRIM(sku_group)) END AS sku_group, ANY_VALUE(sku_class) AS sku_class FROM snitch_db.maplemonk.availability_master_v2 GROUP BY 1 ), collection_count AS ( SELECT collection, COUNT(DISTINCT CASE WHEN REGEXP_LIKE(UPPER(TRIM(sku)), \'^MP[A-Z]{2}[0-9]\') AND NOT REGEXP_LIKE(UPPER(TRIM(sku)), \'^MP-\') THEN \'MP-\' || SUBSTR(UPPER(TRIM(sku)), 3) WHEN REGEXP_LIKE(UPPER(TRIM(sku)), \'.*-[0-9]$\') THEN REGEXP_REPLACE(UPPER(TRIM(sku)), \'-([0-9])$\', \'-0\\1\') ELSE UPPER(TRIM(sku)) END ) AS collection_count FROM snitch_db.maplemonk.collection_sku_mapped GROUP BY collection ), po_sku_colours AS ( SELECT sku_code, COUNT(DISTINCT colour_code) AS po_colours FROM po_base GROUP BY sku_code ), seemi AS ( SELECT TRIM(REGEXP_REPLACE(value::STRING, \'^R\', \'\')) AS sku_group FROM SNITCH_DB.MAPLEMONK.SEEMI, LATERAL SPLIT_TO_TABLE( REPLACE(SKU_GROUP, \' // \', \'//\'), \'//\' ) ), production_merchandiser_mapping AS ( SELECT DISTINCT p.sku_group, CASE WHEN m.sku IS NOT NULL THEN \'MANISH\' WHEN br.sku_group IS NOT NULL THEN \'BHARAT\' WHEN k.sku_group IS NOT NULL THEN \'KHUSHAL\' WHEN s.sku_group IS NOT NULL THEN \'SEEMI\' ELSE \'UNASSIGNED\' END AS production_merchandiser FROM base p LEFT JOIN SNITCH_DB.MAPLEMONK.MANISH m ON UPPER(TRIM(p.sku_group)) = UPPER(TRIM(m.sku)) LEFT JOIN SNITCH_DB.MAPLEMONK.BHARAT br ON UPPER(TRIM(p.sku_group)) = UPPER(TRIM(br.sku_group)) LEFT JOIN SNITCH_DB.MAPLEMONK.KHUSHAL k ON UPPER(TRIM(p.sku_group)) = UPPER(TRIM(k.sku_group)) LEFT JOIN seemi s ON UPPER(TRIM(p.sku_group)) = UPPER(TRIM(s.sku_group)) ), mp_repeat_remarks AS ( WITH mp_base AS ( SELECT REGEXP_REPLACE( UPPER(TRIM(_AIRBYTE_DATA:sku::STRING)), \'^R\', \'\' ) AS sku_group, NULLIF( UPPER(TRIM(_AIRBYTE_DATA:mp_sku::STRING)), \'\' ) AS mp_sku FROM snitch_db.maplemonk._AIRBYTE_RAW_MP_ORDER_FINAL_SHEET_ ), remarks AS ( SELECT sku_group, mp_sku, CASE WHEN sku_group NOT ILIKE \'MP-%\' AND mp_sku IS NOT NULL THEN \'Repeat\' ELSE NULL END AS mp_repeat_remarks FROM mp_base ), exploded AS ( SELECT sku_group AS match_sku, mp_repeat_remarks FROM remarks WHERE sku_group IS NOT NULL UNION ALL SELECT mp_sku AS match_sku, mp_repeat_remarks FROM remarks WHERE mp_sku IS NOT NULL ) SELECT UPPER(TRIM(match_sku)) AS match_sku, MAX( CASE WHEN mp_repeat_remarks = \'Repeat\' THEN \'Repeat\' END ) AS mp_repeat_remarks FROM exploded GROUP BY 1 ), final_base AS ( SELECT b.sku_group, b.sku_code, b.colour_code, B.WAREHOUSE, mm.l1_category, mm.category, mm.meta1, mm.meta2, mm.meta3, mrp.mrp, sc.sku_class, COALESCE(mpr.mp_repeat_remarks, rr.repeat_remarks) AS repeat_remarks, b.vendor_name, pm.production_merchandiser, b.south_qty, b.north_qty, b.total_qty, b.purchase_order, b.inspection_date_north, b.inspection_date_south, b.planned_month, cd.collection, cc.collection_count, CASE WHEN cd.collection IS NOT NULL THEN COUNT(DISTINCT b.sku_group) OVER (PARTITION BY cd.collection) END AS collection_present, pd.shoot_date, pd.sample_received_date, pc.po_colours, COUNT(DISTINCT CASE WHEN b.has_date_of_entry = 1 THEN b.colour_code END) OVER (PARTITION BY b.sku_code) AS colour_count, CASE WHEN COALESCE(mpr.mp_repeat_remarks, rr.repeat_remarks) ILIKE \'Repeat\' THEN pc.po_colours ELSE COUNT(DISTINCT CASE WHEN pd.shoot_date IS NOT NULL THEN b.colour_code WHEN pd.shoot_date IS NULL AND pd.sample_received_date IS NOT NULL AND CURRENT_DATE > DATEADD(day, 3, pd.sample_received_date) THEN b.colour_code END) OVER (PARTITION BY b.sku_code) END AS photoshoot_count FROM po_split b LEFT JOIN photoshoot_dedup pd ON b.sku_group = pd.sku_group LEFT JOIN po_sku_colours pc ON pc.sku_code = b.sku_code LEFT JOIN collection_dedup cd ON cd.sku_group = b.sku_group LEFT JOIN sku_class sc ON sc.sku_group = b.sku_group LEFT JOIN mp_repeat_remarks mpr ON UPPER(TRIM(mpr.match_sku)) = UPPER(TRIM(b.sku_group)) LEFT JOIN repeat_remarks rr ON UPPER(TRIM(rr.sku_group)) = UPPER(TRIM(b.sku_group)) LEFT JOIN collection_count cc ON cc.collection = cd.collection LEFT JOIN meta_mapping mm ON b.sku_group = mm.sku_group LEFT JOIN mrp ON UPPER(TRIM(b.sku_group)) = mrp.sku_group LEFT JOIN production_merchandiser_mapping pm ON UPPER(TRIM(pm.sku_group)) = UPPER(TRIM(b.sku_group)) ), final_with_remarks AS ( SELECT *, CASE WHEN LOWER(category) = \'jeans\' THEN \'JEANS\' WHEN po_colours = colour_count THEN \'COLOURS-READY\' WHEN po_colours > colour_count THEN \'COLOURS-PENDING\' ELSE \'PO-ISSUE\' END AS colour_remarks, CASE WHEN repeat_remarks ilike \'Repeat\' THEN\'Repeat\' WHEN shoot_date IS NULL AND sample_received_date IS NOT NULL AND CURRENT_DATE > DATEADD(day, 3, sample_received_date) THEN \'PHOTOSHOOT - PASS\' WHEN shoot_date IS NULL AND sample_received_date IS NOT NULL THEN \'SAMPLE - RECEIVED\' WHEN sample_received_date IS NULL THEN \'SAMPLE - NOT RECEIVED\' WHEN shoot_date IS NOT NULL THEN \'PHOTOSHOOT - DONE\' END AS photoshoot_remarks, CASE WHEN planned_month ILIKE \'JAN%\' THEN \'JANUARY PLANNED\' WHEN planned_month ILIKE \'FEB%\' THEN \'FEBRUARY PLANNED\' WHEN planned_month ILIKE \'MAR%\' THEN \'MARCH PLANNED\' WHEN planned_month ILIKE \'APR%\' THEN \'APRIL PLANNED\' WHEN planned_month ILIKE \'MAY%\' THEN \'MAY PLANNED\' WHEN planned_month ILIKE \'JUN%\' THEN \'JUNE PLANNED\' WHEN planned_month ILIKE \'JUL%\' THEN \'JULY PLANNED\' WHEN planned_month ILIKE \'AUG%\' THEN \'AUGUST PLANNED\' WHEN planned_month ILIKE \'SEP%\' THEN \'SEPTEMBER PLANNED\' WHEN planned_month ILIKE \'OCT%\' THEN \'OCTOBER PLANNED\' WHEN planned_month ILIKE \'NOV%\' THEN \'NOVEMBER PLANNED\' WHEN planned_month ILIKE \'DEC%\' THEN \'DECEMBER PLANNED\' WHEN planned_month ILIKE \'#N/A\' OR planned_month IS NULL OR TRIM(planned_month) = \'\' THEN \'NOT IN PLANNED\' ELSE \'NOT IN PLANNED\' END AS planned_month_remarks, CASE WHEN planned_month ILIKE \'JAN%\' AND 1 <= MONTH(CURRENT_DATE) THEN 1 WHEN planned_month ILIKE \'FEB%\' AND 2 <= MONTH(CURRENT_DATE) THEN 2 WHEN planned_month ILIKE \'MAR%\' AND 3 <= MONTH(CURRENT_DATE) THEN 3 WHEN planned_month ILIKE \'APR%\' AND 4 <= MONTH(CURRENT_DATE) THEN 4 WHEN planned_month ILIKE \'MAY%\' AND 5 <= MONTH(CURRENT_DATE) THEN 5 WHEN planned_month ILIKE \'JUN%\' AND 6 <= MONTH(CURRENT_DATE) THEN 6 WHEN planned_month ILIKE \'JUL%\' AND 7 <= MONTH(CURRENT_DATE) THEN 7 WHEN planned_month ILIKE \'AUG%\' AND 8 <= MONTH(CURRENT_DATE) THEN 8 WHEN planned_month ILIKE \'SEP%\' AND 9 <= MONTH(CURRENT_DATE) THEN 9 WHEN planned_month ILIKE \'OCT%\' AND 10 <= MONTH(CURRENT_DATE) THEN 10 WHEN planned_month ILIKE \'NOV%\' AND 11 <= MONTH(CURRENT_DATE) THEN 11 WHEN planned_month ILIKE \'DEC%\' AND 12 <= MONTH(CURRENT_DATE) THEN 12 ELSE NULL END AS planned_month_num, CASE WHEN collection_count = collection_present THEN \'COLLECTION - READY\' WHEN collection_count > collection_present THEN \'COLLECTION - PENDING\' ELSE NULL END AS collection_remarks FROM final_base ), final_output AS ( SELECT *, CASE WHEN repeat_remarks = \'Repeat\' AND photoshoot_remarks ilike \'Repeat\' THEN \'ALLOCATABLE\' WHEN sku_group ilike \'MP-%\' and photoshoot_remarks in( \'PHOTOSHOOT - PASS\',\'PHOTOSHOOT - DONE\') THEN \'ALLOCATABLE\' WHEN SKU_GROUP ILIKE \'MP-%\' AND photoshoot_remarks not in ( \'PHOTOSHOOT - PASS\',\'PHOTOSHOOT - DONE\') THEN \'NON-ALLOCATABLE\' WHEN colour_remarks ILIKE \'COLOURS-READY\' AND photoshoot_remarks IN (\'PHOTOSHOOT - DONE\', \'PHOTOSHOOT - PASS\') AND photoshoot_count = po_colours AND (collection_remarks IS NULL OR collection_remarks ILIKE \'COLLECTION - READY\') THEN \'ALLOCATABLE\' WHEN LOWER(category) = \'jeans\' and photoshoot_remarks in (\'PHOTOSHOOT - DONE\',\'PHOTOSHOOT - PASS\') THEN \'ALLOCATABLE\' WHEN colour_remarks ILIKE \'COLOURS-READY\' AND photoshoot_remarks IN (\'PHOTOSHOOT - DONE\', \'PHOTOSHOOT - PASS\') and photoshoot_count = po_colours AND collection_remarks IS NULL THEN \'ALLOCATABLE\' WHEN LOWER(category) = \'jeans\' AND photoshoot_remarks NOT IN (\'PHOTOSHOOT - PASS\',\'PHOTOSHOOT - DONE\') and planned_month NOT IN (\'MAY PLANNED\',\'APRIL PLANNED\') THEN \'NON-ALLOCATABLE\' WHEN colour_remarks ILIKE \'COLOURS-READY\' AND photoshoot_remarks IN (\'PHOTOSHOOT - DONE\', \'PHOTOSHOOT - PASS\') AND planned_month_remarks ILIKE \'NOT IN PLANNED\' THEN \'NON-ALLOCATABLE\' ELSE \'NON-ALLOCATABLE\' END AS final_remarks FROM final_with_remarks ) SELECT *, CASE WHEN final_remarks = \'ALLOCATABLE\' AND repeat_remarks = \'Repeat\' THEN \'REPEAT\' WHEN sku_group ilike \'MP-%\' and final_remarks = \'ALLOCATABLE\' THEN \'MP SKU\' WHEN final_remarks = \'ALLOCATABLE\' AND LOWER(category) = \'jeans\' THEN \'JEANS\' WHEN final_remarks = \'ALLOCATABLE\' AND collection IS NOT NULL THEN \'COLLECTION\' WHEN final_remarks = \'ALLOCATABLE\' and repeat_remarks is null THEN \'NEW\' WHEN colour_remarks ILIKE \'ALLOCATABLE\' AND planned_month_remarks ILIKE \'APRIL PLANNED\' THEN \'APRIL PLANNED\' WHEN final_remarks = \'NON-ALLOCATABLE\' AND colour_remarks = \'COLOURS-PENDING\' THEN \'COLOURS PENDING\' WHEN final_remarks = \'NON-ALLOCATABLE\' AND (photoshoot_remarks IN (\'SAMPLE - RECEIVED\', \'SAMPLE - NOT RECEIVED\') or photoshoot_count < po_colours) THEN \'PHOTOSHOOT PENDING\' WHEN final_remarks = \'NON-ALLOCATABLE\' AND collection_remarks = \'COLLECTION - PENDING\' THEN \'COLLECTION PENDING\' ELSE NULL END AS final_breakdown FROM final_output;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            